// changes: ['/user/name']`)]},{id:"json-write",title:"Write operations",blocks:[D("Compiled setters, inserters and removers for both pointer and JSONPath targets: a singular pointer writes one location; a JSONPath target writes every match. All copy-on-write with the same sharing guarantees as patch."),Q(null,`import { compileJSONPathSetter } from '@jarenjs/json/write';
